def collapse_ints(nums: list[int]) -> str:
    """Sort distinct ints; write runs of 4+ consecutive as first-last."""
    uniq = sorted(set(nums))
    parts: list[str] = []
    i, n = 0, len(uniq)
    while i < n:
        j = i
        while j + 1 < n and uniq[j + 1] == uniq[j] + 1:
            j += 1
        run = uniq[i:j + 1]
        if len(run) >= 4:
            parts.append(f"{_ep(run[0])}-{_ep(run[-1])}")
        else:
            parts.extend(str(x) for x in run)
        i = j + 1
    return ",".join(parts)


def _ep(x: int) -> str:
    """Format a range endpoint: negatives in parentheses."""
    return f"({x})" if x < 0 else str(x)

